syntax:
```c++
constexpr int square(int x) { return x * x; }

int main() {
  constexpr int value = square(5); // Compile-time computation
  int runtime_value = square(10); // Runtime computation
  // ... further use of value and runtime_value
}
```

code_example:
#include <iostream>
#include <array>
constexpr int fibonacci(int n) {
  return n <= 1 ? n : fibonacci(n - 1) + fibonacci(n - 2);
}
int main() {
  constexpr std::array<int, 10> fib_sequence = []() {
    std::array<int, 10> arr; 
    for (int i = 0; i < 10; ++i) arr[i] = fibonacci(i);
    return arr;
  }();
  for (int i = 0; i < 10; ++i) {
    std::cout << fib_sequence[i] << " "; //No runtime computation
  }
  std::cout << std::endl;
  int runtime_fib = fibonacci(20); //Runtime computation
  std::cout << "Runtime fibonacci(20): " << runtime_fib << std::endl;
  return 0;
}
